mapper.update:
update expert_profile
set latest_submit_time = sysdate(), update_time = sysdate()
where user_id = #{userId}

mapper.select:
select 
from expert_material m
where m.user_id = #{userId}

    and m.material_category = #{materialCategory}


    and m.job_status = #{jobStatus}

order by m.material_id desc

select 
from expert_material m
where m.material_id = #{materialId}

select 
from expert_material m
where m.user_id = #{userId}
  and m.material_category = #{categoryCode}
order by m.material_id desc
limit 1

select coalesce(max(version_no), 0)
from expert_material
where user_id = #{userId} and material_category = #{categoryCode}

mapper.delete:
delete from expert_graph_dimension_evidence
where material_id = #{materialId}
  and graph_status = #{graphStatus}

mapper.update:
update expert_profile
set graph_version = graph_version + 1, update_time = sysdate()
where user_id = #{userId}

mapper.select:
select material_id materialId, user_id userId, file_name fileName, material_category materialCategory, job_status jobStatus, review_status reviewStatus, extracted_fields extractedFields, issue_count issueCount, agent_message agentMessage, create_time createTime, update_time updateTime from expert_material
job_status = #{jobStatus}
order by material_id desc
